style.css:
@-moz-document domain("roblox.com") {
.section-content.profile-header-content.ng-scope,
.rbx-tabs-horizontal .nav-tabs *,
.profile-avatar-mask,
.section.layer.profile-collections.ng-scope,
.switcher *,
.section.profile-statistics .section-content {
  background-color: #1f1f1f !important;
}

.section-content.profile-header-content.ng-scope *,
.rbx-tabs-horizontal .nav-tabs *,
.profile-container .asset-item,
.switcher *,
.section.profile-statistics .section-content *,
.profile-about * {
  color: #ffffff !important;
}

.profile-avatar-left {
  background: transparent !important;
}

.section-content, .switcher, .tab-content, .container-footer {
  background-color: #2b2b2b !important;
  color: #ffffff !important;
}

#navigation, .rbx-navbar, .rbx-header, #vertical-menu {
  background-color: #111111 !important;
  color: #ffffff !important;
}
#navigation *, #vertical-menu * {
  color: #ffffff !important;
}

.navbar-search *, .rbx-header .navbar-search .new-dropdown-menu {
  background-color: #3a3a3a !important;
  color: #ffffff !important;
  border-radius: 6px !important;
}

/* Textos principales */
h1, h2, h3, .text-name, .text-robux-lg, .friend-name {
  color: #ffffff !important;
}

.btn-secondary-xs, .btn-more, .text-link, .text-robux-tile {
  background-color: #3b3b3b !important;
  color: #ffffff !important;
  border-radius: 8px !important;
}

.item-details *, .section-content.AddAComment, .text.game-description.linkify {
  color: #e6e6e6 !important;
  background-color: #242424 !important;
}

.chat-body, .dropdown-menu, .dialogs * {
  background-color: #181818 !important;
  color: #ffffff !important;
}

body, .content {
  background: transparent !important;
}

.dark-theme, .light-theme, .nav-content {
  width: 100% !important;
  height: 100% !important;
  background-size: cover !important;
  background-attachment: fixed !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-image: url("https://i.postimg.cc/Hj18HF9K/junior-h.jpg") !important;
  filter: brightness(0.5);
}

#navigation:after {
  position: absolute !important;
  content: "Base style by DittoDino + edit by Val" !important;
  bottom: 5px !important;
  left: 10px !important;
  font-size: 8px !important;
  color: #888 !important;
}
}
